r103 as (
  -- the subjects of 103, resolved now by the rule of 102 and 103 (public.groups, public.idols, decision 17): reason null = in
  select s.slug, s.kind, s.end_year,
         case
           when g.id is null then 'no_groups_row'
           when s.kind = 'group' then (
             select case when count(*) = 0 then case when s.end_year is not null then 'no_member' else 'no_active_member' end
                         when count(x.birth_date) < count(*) then 'unknown_birth_date'
                         when count(*) filter (where x.birth_date <= (current_date - interval '18 years')::date) < count(*) then 'minor_member' end
               from public.idols x where x.group_id = g.id and (x.active or s.end_year is not null))
           else (
             select case when p.n > 1 then 'ambiguous' when p.n = 0 then 'no_idol_row' when p.bd is null then 'unknown_birth_date'
                         when p.bd > (current_date - interval '18 years')::date then 'minor' end
               from (select case when own.n > 0 then own.n else oth.n end as n, case when own.n > 0 then own.bd else oth.bd end as bd
                       from (select count(*) as n, max(x.birth_date) as bd from public.idols x where x.group_id = g.id and x.active) own,
                            (select count(*) as n, max(x.birth_date) as bd from public.idols x
                              where x.group_id <> g.id and x.active and lower(btrim(x.name)) = lower(btrim(g.name))) oth) p)
         end as reason,
         -- the group line of a person whose idols row sits in another group
         case when s.kind = 'idol' and g.id is not null and not exists (select 1 from public.idols x where x.group_id = g.id and x.active) then
           (select gl.slug from public.idols x join public.groups gl on gl.id = x.group_id
             where x.group_id <> g.id and x.active and lower(btrim(x.name)) = lower(btrim(g.name)) limit 1) end as line
    from l103 s left join public.groups g on g.slug = s.slug),
e103 (id) as (
  -- the entities 103 writes: the subjects in, and the group lines of the people in
  select case when kind = 'group' then 'group:' else 'idol:' end || slug from r103 where reason is null
  union select 'group:' || line from r103 where reason is null and line is not null),
x099 as (
  select m.slug, m.name, m.active
    from l099 m join public.groups g on g.slug = m.slug
   where not exists (select 1 from public.idols x where x.group_id = g.id and x.active
                       and coalesce(x.review_reason, '') not like '099-idols-members%' and coalesce(x.review_reason, '') not like '099b-idols-returning%')
     and not (m.kind = 'idol' and exists (
           select 1 from l099 f join public.idols x on x.active and x.group_id <> g.id
            where f.slug = m.slug and f.pos = 0
              and coalesce(x.review_reason, '') not like '099-idols-members%' and coalesce(x.review_reason, '') not like '099b-idols-returning%'
              and (lower(btrim(x.name)) = lower(btrim(f.name)) or x.wikidata_qid = f.qid)))
     and not exists (select 1 from public.idols x where x.group_id = g.id and x.name = m.name
                       and coalesce(x.review_reason, '') not like '099-idols-members%' and coalesce(x.review_reason, '') not like '099b-idols-returning%')),
x099b as (
  select m.slug, m.name
    from l099b m join public.groups g on g.slug = m.slug
   where not exists (select 1 from public.idols x where x.group_id = g.id and x.active and coalesce(x.review_reason, '') not like '099b-idols-returning%')
     and not exists (select 1 from public.idols x where x.group_id = g.id and x.name = m.name and coalesce(x.review_reason, '') not like '099b-idols-returning%')),
checks as (
  select 1 as n, '099-idols-members.sql' as fichier, 'line 22: rows of 099 = the members of its list whose subject had no active member (the "N rows added" notice)' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select (select count(*)::text from x099) as a,
                 (select count(*)::text from public.idols where review_reason like '099-idols-members%') as o) x
  union all
  select 2 as n, '099-idols-members.sql' as fichier, 'line 23: one line per subject added, slug active count (former members of loossemble, miss-a, purple-kiss, sistar)' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select (select coalesce(string_agg(slug || ' ' || active || ' ' || n, ', ' order by slug, active), '') from (select slug, active, count(*) as n from x099 group by slug, active) z) as a,
                 (select coalesce(string_agg(slug || ' ' || active || ' ' || n, ', ' order by slug, active), '') from (select g.slug, i.active, count(*) as n
     from public.idols i join public.groups g on g.id = i.group_id where i.review_reason like '099-idols-members%' group by g.slug, i.active) z) as o) x
  union all
  select 3 as n, '099-idols-members.sql' as fichier, 'line 24: active rows of 099 out of the Kpopdle wait' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select '0' as a,
                 (select count(*)::text from public.idols where review_reason like '099-idols-members%' and active and not needs_review) as o) x
  union all
  select 4 as n, '099-idols-members.sql' as fichier, 'line 25: rows of 099 in the Kpopdle source view' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select case when to_regclass('public.dle_src_kpop_idol') is not null then '0' else 'no view dle_src_kpop_idol' end as a,
                 coalesce(case when to_regclass('public.dle_src_kpop_idol') is not null then convert_from(decode(substring(query_to_xml($q$select encode(convert_to((select count(*) from public.dle_src_kpop_idol s join public.idols i on i.id::text = s.entity_id where i.review_reason like '099-idols-members%')::text, 'UTF8'), 'hex') as v$q$, true, false, '')::text from '<v>([0-9a-f]*)</v>'), 'hex'), 'UTF8') end, 'no view dle_src_kpop_idol') as o) x
  union all
  select 5 as n, '102-catalog-rebuild.sql' as fichier, 'line 26: cards owned and packs opened (none before the first pack: the numbers may still change)' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select '0 owned, 0 packs' as a,
                 (select (select count(*) from public.cards_owned) || ' owned, ' || (select count(*) from public.cards_packs) || ' packs') as o) x
  union all
  select 6 as n, '102-catalog-rebuild.sql' as fichier, 'line 27: cards per part = the edition rule of 103 on the photos live now: a person one card an edition, a group a pair (true after Reconstruire le catalogue)' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select (select format('0: %s, 1: %s, 2: %s', coalesce(sum(r.editions) filter (where r.kind = 'idol'), 0),
       coalesce(sum(r.editions) filter (where r.kind = 'group'), 0), coalesce(sum(r.editions) filter (where r.kind = 'group'), 0)) from (select z.kind, case when z.n < 2 then 0 when z.n = 6 and not z.full_any then 5 else z.n end as editions
       from (select e.id, e.kind, least(count(*), 6) as n,
                    bool_or(case when e.kind = 'group' then w.cw / 2 >= 640 else w.cw >= 640 end) as full_any
               from public.cards_entities e
               join public.cards_photos p on p.entity_id = e.id and p.status in ('auto', 'approved') and p.source_width is not null and p.source_height is not null
               cross join lateral (select floor(least(p.source_width::numeric, p.source_height::numeric * (case when e.kind = 'group' then 11 else 5.5 end) / 8.5))::integer as cw) w
              where e.kind in ('idol', 'group')
              group by e.id, e.kind) z) r) as a,
                 case when exists (select 1 from pg_attribute where attrelid = to_regclass('public.cards_catalog') and attname = 'part' and attnum > 0 and not attisdropped) then convert_from(decode(substring(query_to_xml($q$select encode(convert_to((select format('0: %s, 1: %s, 2: %s', count(*) filter (where part = 0), count(*) filter (where part = 1), count(*) filter (where part = 2)) from public.cards_catalog)::text, 'UTF8'), 'hex') as v$q$, true, false, '')::text from '<v>([0-9a-f]*)</v>'), 'hex'), 'UTF8') end as o) x
  union all
  select 7 as n, '102-catalog-rebuild.sql' as fichier, 'line 28: numbers 1 to N, contiguous' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select (select case when x.n = 0 then '-, -, 0' else '1, ' || x.n || ', ' || x.n end from (select (select count(*) from public.cards_catalog)::bigint as n) x) as a,
                 (select coalesce(min(card_no)::text, '-') || ', ' || coalesce(max(card_no)::text, '-') || ', ' || count(*) from public.cards_catalog) as o) x
  union all
  select 8 as n, '102-catalog-rebuild.sql' as fichier, 'line 29: pairs without consecutive numbers' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select '0' as a,
                 case when exists (select 1 from pg_attribute where attrelid = to_regclass('public.cards_catalog') and attname = 'part' and attnum > 0 and not attisdropped) then convert_from(decode(substring(query_to_xml($q$select encode(convert_to((select count(*) from public.cards_catalog a join public.cards_catalog b on b.entity_id = a.entity_id and b.rarity = a.rarity and b.part = 2
     where a.part = 1 and b.card_no <> a.card_no + 1)::text, 'UTF8'), 'hex') as v$q$, true, false, '')::text from '<v>([0-9a-f]*)</v>'), 'hex'), 'UTF8') end as o) x
  union all
  select 9 as n, '102-catalog-rebuild.sql' as fichier, 'line 30: subjects the age rule of 102 leaves out that have an entity (after the bundle: only those 103 brings back with newer photos, resolved now)' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select (select coalesce(string_agg(a.id, ', ' order by a.pos), '') from age102 a where a.id in (select id from e103)) as a,
                 (select coalesce(string_agg(a.id, ', ' order by a.pos), '') from age102 a where exists (select 1 from public.cards_entities e where e.id = a.id)) as o) x
  union all
  select 10 as n, '102-catalog-rebuild.sql' as fichier, 'line 31: slugs without their October photo (after the bundle: the slugs whose 103 subject is out or carries no such photo)' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select (select coalesce(string_agg(l.slug, ', ' order by l.pos), '') from lot1 l where not exists (select 1 from r103 r where r.slug = l.subject and r.reason is null)) as a,
                 (select coalesce(string_agg(l.slug, ', ' order by l.pos), '') from lot1 l where not exists (select 1 from public.cards_photos p where p.source_path = 'images/group-photos/' || l.slug || '.jpg')) as o) x
  union all
  select 11 as n, '099b-idols-returning.sql' as fichier, 'line 17: rows of 099b = the members of its list whose group had no active member (the "N rows added" notice)' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select (select count(*)::text from x099b) as a,
                 (select count(*)::text from public.idols where review_reason like '099b-idols-returning%') as o) x
  union all
  select 12 as n, '099b-idols-returning.sql' as fichier, 'line 18: active rows of 099b out of the Kpopdle wait' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select '0' as a,
                 (select count(*)::text from public.idols where review_reason like '099b-idols-returning%' and active and not needs_review) as o) x
  union all
  select 13 as n, '099b-idols-returning.sql' as fichier, 'line 19: one line per group added, slug count' as controle, a as attendu, o as obtenu, coalesce(a = o, false) as ok
    from (select (select coalesce(string_agg(slug || ' ' || n, ', ' order by slug), '') from (select slug, count(*) as n from x099b group by slug) z) as a,
                 (select coalesce(string_agg(slug || ' ' || n, ', ' order by slug), '') from (select g.slug, count(*) as n from public.idols i join public.groups g on g.id = i.group_id
     where i.review_reason like '099b-idols-returning%' group by g.slug) z) as o) x
  union all
