    from (select 'false' as a,
                 case when to_regprocedure('public.cards_catalog_append(boolean)') is not null then (has_function_privilege('anon', to_regprocedure('public.cards_catalog_append(boolean)'), 'execute')
     or has_function_privilege('authenticated', to_regprocedure('public.cards_catalog_append(boolean)'), 'execute'))::text end as o) x
