  select n, fichier, controle, attendu, obtenu, ok from checks
  union all
  select 86, 'ALL-099-115.sql', 'TOUT_OK', 'true', coalesce(bool_and(ok) and count(*) = 85, false)::text, coalesce(bool_and(ok) and count(*) = 85, false) from checks
) r
order by n;
